#pragma GCC optimize("Ofast")
const unsigned long long LIMIT = 1000000000000000000ULL; 

vector<unsigned long long> gen(int n, const vector<unsigned long long>& p) {
    vector<unsigned long long> res;
    res.reserve((size_t)2000000ULL);
    res.push_back(1ULL);

    vector<size_t> idx(n, 0);
    vector<unsigned long long> cand(n);
    for (int j = 0; j < n; ++j) cand[j] = p[j]; 

    while (true) {
        unsigned long long best = ULLONG_MAX;
        for (int j = 0; j < n; ++j) {
            if (cand[j] != 0 && cand[j] < best) best = cand[j];
        }
        if (best == ULLONG_MAX || best > LIMIT) break; 
        res.push_back(best);

        for (int j = 0; j < n; ++j) {
            if (cand[j] == best) {
                ++idx[j];
                __int128 prod = (__int128)p[j] * (__int128)res[idx[j]];
                if (prod > LIMIT) cand[j] = 0; 
                else cand[j] = (unsigned long long)prod;
            }
        }
    }
    return res;
}
long long count_leq(const vector<unsigned long long>& a, const vector<unsigned long long>& b, unsigned long long x) {
    long long cnt = 0;
    int n = (int)a.size(), m = (int)b.size();
    int j = m - 1;
    for (int i = 0; i < n; ++i) {

        while (j >= 0 && (__int128)a[i] * (__int128)b[j] > x) --j;
        if (j < 0) break; 
        cnt += (j + 1);
    }
    return cnt;
}

pair<int,int> kth_pair(const vector<unsigned long long>& a, const vector<unsigned long long>& b, unsigned long long k) {
    int n = (int)a.size(), m = (int)b.size();
    unsigned long long lo = a.front() * b.front();
    unsigned long long hi = a.back() * b.back();
    unsigned long long ans = hi;

    while (lo <= hi) {
        unsigned long long mid = lo + (hi - lo) / 2;
        if (count_leq(a, b, mid) >= (long long)k) {
            ans = mid;
            if (mid == 0) break;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }

    unsigned long long less_cnt = 0;
    if (ans > 0) less_cnt = (unsigned long long)count_leq(a, b, ans - 1);
    unsigned long long need = k - less_cnt; 

    for (int i = 0; i < n; ++i) {
        if (ans % a[i] != 0) continue;
        unsigned long long target = ans / a[i];
        auto lb = std::lower_bound(b.begin(), b.end(), target);
        if (lb == b.end() || *lb != target) continue;
        auto ub = std::upper_bound(b.begin(), b.end(), target);
        unsigned long long occ = (unsigned long long)(ub - lb);
        if (need <= occ) {
            int j_index = (int)((lb - b.begin()) + (need - 1));
            return {i, j_index};
        } else {
            need -= occ;
        }
    }
    return {-1, -1};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<unsigned long long> p(n);
    for (int i = 0; i < n; ++i) cin >> p[i];
    shuffle(p.begin(), p.end(), default_random_engine(39));
    unsigned long long k;
    cin >> k;

    size_t const half_size = p.size() / 2;
    vector<unsigned long long> split_lo(p.begin(), p.begin() + half_size);
    vector<unsigned long long> split_hi(p.begin() + half_size, p.end());

    auto lo = gen(split_lo.size(), split_lo);
    auto hi = gen(split_hi.size(), split_hi);

    pair<int, int> ans = kth_pair(lo, hi, k);

    cout << lo[ans.first] * hi[ans.second] << "\n";
}